# Ici, un script tient le rôle du modèle de langage : sa « décision » vient d'une politique écrite à la main.
# L'outil, lui, est réel : il calcule vraiment.
import ast
import operator

OPERATEURS = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}


def calcul(expression: str) -> float:
    """Évalue une expression arithmétique simple, sans eval() : on n'accepte que + - * / et des nombres."""
    def evaluer(noeud):
        if isinstance(noeud, ast.Constant) and isinstance(noeud.value, (int, float)):
            return noeud.value
        if isinstance(noeud, ast.BinOp) and type(noeud.op) in OPERATEURS:
            return OPERATEURS[type(noeud.op)](evaluer(noeud.left), evaluer(noeud.right))
        raise ValueError(f"expression non autorisée : {expression!r}")
    return evaluer(ast.parse(expression, mode="eval").body)


OUTILS = {"calcul": calcul}


def politique(historique):
    """Le « modèle » : lit tout l'historique et renvoie soit un appel d'outil, soit une réponse finale."""
    observations = [m["contenu"] for m in historique if m["role"] == "outil"]
    if len(observations) == 0:
        return {"appel": ("calcul", {"expression": "1200 * 0.20"})}  # étape 1 : la TVA
    if len(observations) == 1:
        tva = observations[0]
        return {"appel": ("calcul", {"expression": f"1200 + {tva}"})}  # étape 2 : le total, avec la valeur observée
    return {"reponse": f"La TVA est de {observations[0]} euros, le total TTC de {observations[1]} euros."}


def boucle(question, max_tours=5):
    historique = [{"role": "utilisateur", "contenu": question}]
    for tour in range(1, max_tours + 1):
        decision = politique(historique)  # 1. décider (rôle tenu par le script)
        if "reponse" in decision:  # 2. condition d'arrêt : une réponse finale
            print(f"tour {tour} | réponse finale : {decision['reponse']}")
            return decision["reponse"]
        nom, arguments = decision["appel"]
        print(f"tour {tour} | appel demandé : {nom}({arguments})")
        resultat = OUTILS[nom](**arguments)  # 3. agir : le programme exécute, pas le « modèle »
        print(f"tour {tour} | observation   : {resultat}")
        historique.append({"role": "outil", "contenu": resultat})  # 4. observer : le résultat entre dans l'historique
    print("arrêt : nombre maximal de tours atteint")


boucle("Quelle est la TVA à 20 % sur 1200 euros, et quel est le total TTC ?")

