# Ici, un script tient le rôle du modèle de langage. Les messages imitent le FORMAT de la documentation
# d'Anthropic (blocs tool_use / tool_result), mais aucun appel n'est fait à une API.
import ast
import json
import operator
import tempfile
from pathlib import Path

# 1. Les outils : de vraies fonctions Python.
OPERATEURS = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
CAPITALES = {"france": "Paris", "japon": "Tokyo", "suisse": "Berne", "canada": "Ottawa"}
DOSSIER = Path(tempfile.mkdtemp(prefix="agent_"))
(DOSSIER / "notes.txt").write_text("Réunion jeudi à 14 h. Apporter le budget.", encoding="utf-8")


def calcul(expression):
    def evaluer(n):
        if isinstance(n, ast.Constant) and isinstance(n.value, (int, float)):
            return n.value
        if isinstance(n, ast.BinOp) and type(n.op) in OPERATEURS:
            return OPERATEURS[type(n.op)](evaluer(n.left), evaluer(n.right))
        raise ValueError("expression non autorisée")
    return evaluer(ast.parse(expression, mode="eval").body)


def chercher(pays):
    return CAPITALES[pays.lower()]  # KeyError si le pays est inconnu


def lire_fichier(nom):
    chemin = (DOSSIER / nom).resolve()
    if DOSSIER.resolve() not in chemin.parents:
        raise PermissionError("lecture hors du dossier autorisé")
    return chemin.read_text(encoding="utf-8")


# 2. Le catalogue présenté au modèle : nom, description, schéma JSON des paramètres.
CATALOGUE = [
    {"name": "calcul", "description": "Calcule une expression arithmétique (+ - * /). Ne gère pas les fonctions.",
     "input_schema": {"type": "object", "properties": {"expression": {"type": "string"}}, "required": ["expression"]}},
    {"name": "chercher", "description": "Renvoie la capitale d'un pays du petit dictionnaire (en minuscules ou non).",
     "input_schema": {"type": "object", "properties": {"pays": {"type": "string"}}, "required": ["pays"]}},
    {"name": "lire_fichier", "description": "Lit un fichier texte du dossier de travail temporaire.",
     "input_schema": {"type": "object", "properties": {"nom": {"type": "string"}}, "required": ["nom"]}},
]
FONCTIONS = {"calcul": calcul, "chercher": chercher, "lire_fichier": lire_fichier}


def valider(appel):
    """Le programme hôte vérifie l'appel avant de l'exécuter : outil connu, paramètres obligatoires présents."""
    schema = next((t["input_schema"] for t in CATALOGUE if t["name"] == appel["name"]), None)
    if schema is None:
        return f"outil inconnu : {appel['name']}"
    manquants = [p for p in schema["required"] if p not in appel["input"]]
    return f"paramètres manquants : {manquants}" if manquants else None


def executer(appel):
    """Renvoie le bloc tool_result correspondant à un bloc tool_use."""
    erreur = valider(appel)
    if erreur is None:
        try:
            return {"type": "tool_result", "tool_use_id": appel["id"], "content": str(FONCTIONS[appel["name"]](**appel["input"]))}
        except Exception as e:  # l'échec devient une observation, pas un plantage
            erreur = f"{type(e).__name__} : {e}"
    return {"type": "tool_result", "tool_use_id": appel["id"], "content": erreur, "is_error": True}


# 3. Trois appels écrits à la main : deux valides (dont deux outils appelés dans le même tour), un invalide.
tour_1 = [  # appels « parallèles » : indépendants, donc demandés ensemble
    {"type": "tool_use", "id": "toolu_1", "name": "chercher", "input": {"pays": "Japon"}},
    {"type": "tool_use", "id": "toolu_2", "name": "lire_fichier", "input": {"nom": "notes.txt"}},
]
tour_2 = [{"type": "tool_use", "id": "toolu_3", "name": "calcul", "input": {}}]  # paramètre obligatoire oublié

for numero, appels in enumerate([tour_1, tour_2], start=1):
    print(f"--- tour {numero} : message de l'assistant (rôle tenu par le script) ---")
    print(json.dumps(appels, ensure_ascii=False))
    resultats = [executer(a) for a in appels]
    print(f"--- tour {numero} : message de l'utilisateur renvoyé par le programme ---")
    for r in resultats:
        print(json.dumps(r, ensure_ascii=False))

