# Ici, un script tient le rôle du modèle. On mesure ce que le programme hôte renverrait au modèle à chaque tour
# (en caractères, pas en tokens) si l'on garde les résultats d'outils bruts, ou si l'on ne garde que des notes.
import re

# Trois « pages » volumineuses renvoyées par un outil de lecture : du bruit autour de quelques faits.
BRUIT = "menu | accueil | cookies | mentions légales | newsletter | panier | " * 60
PAGES = {
    "fiche_a": BRUIT + "Prix : 450 euros. Garantie : 2 ans. " + BRUIT,
    "fiche_b": BRUIT + "Prix : 420 euros. Garantie : 1 an. " + BRUIT,
    "fiche_c": BRUIT + "Prix : 480 euros. Garantie : 3 ans. " + BRUIT,
}
CONSIGNE = "Compare les trois fiches et dis laquelle a le meilleur rapport prix / garantie."


def extraire_faits(nom, page):
    prix = re.search(r"Prix : (\d+) euros", page).group(1)
    garantie = re.search(r"Garantie : (\d+) an", page).group(1)
    return f"{nom} : prix {prix} euros, garantie {garantie} an(s)"


def taille(messages):
    return sum(len(m) for m in messages)


def simuler(garder_brut):
    messages = [CONSIGNE]  # ce qui est renvoyé au modèle à chaque tour
    notes = []
    total_envoye = 0
    for nom, page in PAGES.items():
        total_envoye += taille(messages)  # chaque appel au modèle renvoie tout l'historique
        if garder_brut:
            messages.append(page)  # le résultat brut reste dans l'historique
        else:
            notes.append(extraire_faits(nom, page))  # seule une note de quelques mots est gardée
            messages = [CONSIGNE, "Notes : " + " ; ".join(notes)]
    total_envoye += taille(messages)  # dernier tour : la réponse finale
    return taille(messages), total_envoye


for libelle, brut in [("résultats bruts conservés", True), ("notes extraites seulement", False)]:
    final, cumul = simuler(brut)
    print(f"{libelle:28s} | taille finale : {final:6d} caractères | total envoyé en 4 appels : {cumul:7d} caractères")

# Ici, un script tient le rôle du modèle de langage : deux politiques écrites à la main, l'une qui lit
# les messages d'erreur, l'autre qui s'entête. Le programme hôte (la boucle) et l'outil sont réels.
import ast
import json
import operator

OPERATEURS = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}


def calcul(expression):
    def evaluer(n):
        if isinstance(n, ast.Constant) and isinstance(n.value, (int, float)):
            return n.value
        if isinstance(n, ast.BinOp) and type(n.op) in OPERATEURS:
            return OPERATEURS[type(n.op)](evaluer(n.left), evaluer(n.right))
        raise ValueError("expression non autorisée : écrivez les décimales avec un point (0.2) et utilisez seulement + - * /")
    return evaluer(ast.parse(expression, mode="eval").body)


def politique_attentive(observations):
    """Lit la dernière observation. Si c'est une erreur qui parle de décimales, corrige l'expression."""
    if not observations:
        return {"appel": {"expression": "1200 * 0,2"}}  # première tentative : virgule décimale (erreur courante)
    derniere = observations[-1]
    if derniere["erreur"]:
        corrigee = derniere["appel"]["expression"].replace(",", ".")  # l'erreur dit quoi changer
        return {"appel": {"expression": corrigee}}
    return {"reponse": f"La TVA est de {derniere['resultat']} euros."}


def politique_entetee(observations):
    """Ne tient aucun compte des observations : répète toujours le même appel."""
    return {"appel": {"expression": "1200 * 0,2"}}


def boucle(politique, max_tours=6, max_repetitions=2):
    observations = []
    echecs_identiques = {}
    for tour in range(1, max_tours + 1):
        decision = politique(observations)
        if "reponse" in decision:
            print(f"  tour {tour} : réponse finale -> {decision['reponse']}")
            return "reponse"
        signature = json.dumps(decision["appel"], sort_keys=True)
        if echecs_identiques.get(signature, 0) >= max_repetitions:  # garde-fou : même appel déjà échoué
            print(f"  tour {tour} : appel {signature} bloqué par le programme (déjà échoué {max_repetitions} fois)")
            return "repetition"
        try:
            observations.append({"appel": decision["appel"], "resultat": calcul(**decision["appel"]), "erreur": None})
            print(f"  tour {tour} : {signature} -> {observations[-1]['resultat']}")
        except Exception as e:
            echecs_identiques[signature] = echecs_identiques.get(signature, 0) + 1
            observations.append({"appel": decision["appel"], "resultat": None, "erreur": str(e)})
            print(f"  tour {tour} : {signature} -> ERREUR : {e}")
    return "limite_tours"


for nom, politique in [("politique attentive", politique_attentive), ("politique entêtée", politique_entetee)]:
    print(nom)
    print("  arrêt :", boucle(politique))
